function addMonths(date,n){const [y,m,d]=date.split('-').map(Number),v=new Date(Date.UTC(y,m-1+n,1));v.setUTCDate(Math.min(d,new Date(Date.UTC(v.getUTCFullYear(),v.getUTCMonth()+1,0)).getUTCDate()));return v.toISOString().slice(0,10);}
function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
