const frequencies=()=>[{value:'once',label:tr('دفعة واحدة','One payment')},{value:'monthly',label:tr('شهري','Monthly')},{value:'quarterly',label:tr('كل 3 أشهر','Quarterly')},{value:'halfyearly',label:tr('كل 6 أشهر','Half yearly')},{value:'yearly',label:tr('سنوي','Yearly')}];
function planFields(form,initial={}){field(form,'pricing_basis',tr('القيمة محسوبة على أساس','Price is per'),{options:[{value:'yearly',label:tr('سنة','Year')},{value:'monthly',label:tr('شهر','Month')},{value:'daily',label:tr('يوم','Day')},{value:'total',label:tr('إجمالي العقد','Entire contract')}],value:initial.pricing_basis||'yearly',required:true});field(form,'unit_price',tr('القيمة — ريال','Price — SAR'),{type:'number',min:'.01',step:'.01',required:true,value:initial.unit_price});const start=field(form,'start_date',tr('بداية العقد','Contract starts'),{type:'date',required:true,value:initial.start_date||today()});field(form,'end_date',tr('آخر يوم بالعقد','Last contract day'),{type:'date',required:true,value:initial.end_date||addDays(addMonths(today(),12),-1)});const freq=field(form,'frequency',tr('طريقة توزيع الدفعات','Payment frequency'),{options:frequencies(),value:initial.frequency||'quarterly',required:true});const count=field(form,'count',tr('عدد الدفعات','Number of payments'),{type:'number',min:1,max:120,step:1,required:true,value:initial.count||4});const first=field(form,'first_due',tr('موعد أول دفعة','First payment due'),{type:'date',required:true,value:initial.first_due||start.value});start.addEventListener('change',()=>{first.value=start.value;});freq.addEventListener('change',()=>{count.value=({once:1,monthly:12,quarterly:4,halfyearly:2,yearly:1})[freq.value]||1;});
 const end=form.querySelector('[name=end_date]');let customCount=false;count.addEventListener('input',()=>customCount=true);const autoCount=()=>{if(customCount)return;const step=({monthly:1,quarterly:3,halfyearly:6,yearly:12})[freq.value];if(!step){count.value=1;return;}if(!first.value||!end.value)return;let n=0;while(n<120&&addMonths(first.value,n*step)<=end.value)n++;count.value=Math.max(1,n);};freq.addEventListener('change',()=>{customCount=false;autoCount();});first.addEventListener('change',autoCount);end.addEventListener('change',autoCount);start.addEventListener('change',autoCount);autoCount();
 const note=document.createElement('p');note.className='hv-note wide';note.textContent=tr('القيمة تختلف عن طريقة الدفع: يمكنك إدخال إيجار سنوي وتسديده شهريًا. البداية والنهاية محسوبتان ضمن المدة؛ كسر الشهر أو السنة يُحسب بنسبة الأيام.','Price and payment frequency are separate: annual rent may be paid monthly. Both boundary dates are included; partial months or years are prorated by days.');form.append(note);
}
