screenContracts=async function(el){const data=await api('advacon_housing_contracts');if(!el.isConnected)return;const bar=header(el,tr('العقود والمستحقات','Contracts & dues'),tr('ملف لكل عقد، وجدول واحد لمتابعة جميع الدفعات.','One contract file and one ledger for all payments.'));if(can('contracts.create'))bar.append(button(tr('عقد جديد','New contract'),()=>contractWizard(null,null,null),true));el.insertAdjacentHTML('beforeend','<nav class="hv-tabs"><a class="active" href="#contracts">'+tr('العقود','Contracts')+'</a><a href="#obligations">'+tr('المستحقات والدفع','Dues & payments')+'</a></nav><div class="hv-toolbar"><input type="search" placeholder="'+tr('ابحث بالعقد أو الجهة أو المكان','Search contract, payee or place')+'" aria-label="'+tr('بحث العقود','Search contracts')+'"><label>'+tr('العرض','Show')+'<select><option value="all">'+tr('كل العقود','All contracts')+'</option><option value="active">'+tr('السارية','Active')+'</option><option value="expiring">'+tr('قرب الانتهاء','Expiring')+'</option><option value="unscheduled">'+tr('بدون جدول دفعات','Without payment schedule')+'</option></select></label></div><section class="hv-panel" id="hv-contract-list"></section>');const filter=el.querySelector('select');if(new URLSearchParams(location.hash.split('?')[1]).has('expiring'))filter.value='expiring';if(new URLSearchParams(location.hash.split('?')[1]).has('unscheduled'))filter.value='unscheduled';const draw=()=>{const q=el.querySelector('input').value.toLowerCase(),f=filter.value;const rows=data.items.filter(c=>([c.title,c.contract_no,c.property_name,c.landlord].join(' ').toLowerCase().includes(q))&&(f!=='active'||c.status_key==='active')&&(f!=='expiring'||c.status_key==='active'&&c.end_date>=today()&&c.end_date<=addDays(today(),30))&&(f!=='unscheduled'||Number(c.schedule_count)===0));const box=el.querySelector('#hv-contract-list');box.innerHTML=rows.length?contractTable(rows):empty();bindContracts(box,rows,()=>screenContracts(el));};el.querySelector('input').oninput=draw;filter.onchange=draw;draw();};
async function contractDetail(id,reload=()=>route()){
 const data=await api('advacon_housing_contracts'),c=data.items.find(x=>x.id===id);if(!c)throw Error('contract_not_found');const fin=await financeOptional();const body=document.createElement('div'),footer=document.createElement('div');footer.className='hv-foot';const m=openModal({title:c.title||c.contract_no||tr('ملف العقد','Contract file'),body,footer,wide:true});body.innerHTML='<p class="hv-muted">'+esc(c.landlord||'—')+' · '+esc(c.property_name||tr('عقد خارجي مستقل','Independent external contract'))+'</p>'+kpis([[tr('من','From'),fmtDate(c.start_date)],[tr('إلى','To'),fmtDate(c.end_date)],[tr('القيمة','Value'),fmtSAR(c.total_value)],[tr('عدد الدفعات','Payments'),c.schedule_count]])+'<p>'+esc(c.notes||'')+'</p><div class="hv-contract-dues"></div><details class="hv-menu"><summary>'+tr('مرفقات العقد','Contract documents')+'</summary><div class="hv-documents"></div></details>';
 if(fin){const rows=activeDues(fin).filter(d=>d.contract_id===id),box=body.querySelector('.hv-contract-dues');box.innerHTML=rows.length?table(dueHeaders(),dueRows(rows,fin.as_of)):empty(tr('العقد محفوظ، ولم يُنشأ جدول دفعات له بعد.','Contract saved; no payment schedule yet.'));bindDues(box,fin,async()=>{m.close();await contractDetail(id,reload);});}
 const refresh=async()=>{m.close();await reload();};if(can('contracts.create'))footer.append(button(tr('تجديد بعقد جديد','Renew with a new contract'),()=>contractWizard(c.property_id,c,null,refresh)));
 if(!Number(c.schedule_count)&&can('contracts.edit'))footer.append(button(tr('إنشاء جدول الدفعات','Create payment schedule'),()=>scheduleLegacy(c,refresh),true));
 if(can('contracts.edit'))footer.append(button(tr('تعديل بيانات العقد','Edit contract details'),()=>dialog(tr('بيانات العقد','Contract details'),form=>{field(form,'title',tr('اسم العقد','Contract title'),{value:c.title||c.contract_no,required:true,wide:true});field(form,'contract_no',tr('رقم العقد الخارجي','External reference'),{value:c.contract_no});field(form,'ejar_ref',tr('مرجع إجار','Ejar reference'),{value:c.ejar_ref});field(form,'account_ref',tr('مرجع الحساب','Account reference'),{value:c.account_ref});field(form,'notes',tr('ملاحظات','Notes'),{value:c.notes,type:'textarea',wide:true});},async(v,key)=>{await api('advacon_housing_contract_details',{p_command_id:key,p_payload:{...v,id:c.id,expected_updated_at:c.updated_at||null}});await refresh();})));
 await documents(body.querySelector('.hv-documents'),'contract',id,()=>documents(body.querySelector('.hv-documents'),'contract',id));
}
async function documents(el,type,id,reload){if(!can('attachments.view')){el.textContent=tr('لا توجد صلاحية لعرض المرفقات.','Attachment access is unavailable.');return;}const r=await api('housing_list_attachments',{p_entity_type:type,p_entity_id:id});if(!el.isConnected)return;el.innerHTML='';if(can('attachments.upload')){const input=document.createElement('input');input.type='file';input.setAttribute('aria-label',tr('رفع مرفق','Upload attachment'));input.onchange=()=>{if(input.files[0])handleAttachmentUpload(input.files[0],type,id,reload);};el.append(input);}for(const a of r.items||[]){el.append(button(a.filename||tr('مرفق','Attachment'),async()=>{const result=await api('housing_get_attachment',{p_id:a.id});const file=result.attachment||result;const {data,error}=await sb.storage.from('housing-attachments').createSignedUrl(file.storage_path,120);if(error)throw error;window.open(data.signedUrl,'_blank','noopener');}));}if(!r.items?.length)el.append(document.createTextNode(tr('لا توجد مرفقات.','No attachments.')));}
function scheduleLegacy(c,reload){let validate;const payload=v=>({...v,start_date:c.start_date,end_date:c.end_date,pricing_basis:'total',unit_price:c.total_value});dialog(tr('جدولة دفعات العقد','Schedule contract payments'),(form,m,save)=>{const note=document.createElement('p');note.className='hv-note wide';note.textContent=(c.title||c.contract_no||'')+' · '+fmtSAR(c.total_value)+' · '+fmtDate(c.start_date)+' — '+fmtDate(c.end_date);form.append(note);field(form,'frequency',tr('دورية الدفع','Payment frequency'),{options:frequencies(),value:'quarterly',required:true});field(form,'count',tr('عدد الدفعات','Payments'),{type:'number',min:1,max:120,value:4,required:true});field(form,'first_due',tr('موعد أول دفعة','First due'),{type:'date',value:c.start_date,required:true});validate=previewPlan(form,save,payload);},async(v,key)=>{validate(v);await api('advacon_housing_contract_schedule',{p_command_id:key,p_payload:{id:c.id,...v}});await reload();});}

function bindDues(el,data,reload){el.querySelectorAll('[data-due]').forEach(cell=>{const d=data.dues.find(x=>x.id===cell.dataset.due);cell.append(button(tr('التفاصيل والدفع','Details & payment'),()=>dueDetail(d,data,reload)));});}
async function dueDetail(d,data,reload){const body=document.createElement('div'),footer=document.createElement('div');footer.className='hv-foot';const m=openModal({title:d.label,body,footer,wide:true});const payments=data.payments.filter(x=>x.due_id===d.id);body.innerHTML='<p>'+esc(d.payee)+' · '+(d.due_date_estimated?tr('موعد غير محدد','No confirmed due date'):fmtDate(d.due_date))+'</p>'+kpis([[tr('المبلغ','Amount'),fmtSAR(d.amount)],[tr('مدفوع','Paid'),fmtSAR(d.paid)],[tr('متبقٍ','Remaining'),fmtSAR(d.remaining)]])+(Number(d.legacy_paid_amount)?'<p class="hv-note">'+tr('دفع مسجل سابقًا على الفاتورة: ','Previously recorded bill payment: ')+fmtSAR(d.legacy_paid_amount)+' · '+fmtDate(d.legacy_paid_date)+'</p>':'')+table([tr('تاريخ الدفع','Paid on'),tr('المرجع','Reference'),tr('المبلغ','Amount'),''],payments.map(p=>'<tr><td>'+fmtDate(p.paid_on)+'</td><td>'+esc(p.reference)+(p.reversal_of?' · '+tr('عكس دفعة','Reversal'):'')+'</td><td>'+fmtSAR((p.reversal_of?-1:1)*Number(p.amount))+'</td><td data-payment="'+esc(p.id)+'"></td></tr>'));
 const refresh=async()=>{m.close();await reload();};if(data.can_manage!==false&&!d.cancelled&&Number(d.remaining)>0)footer.append(button(tr('تسجيل دفعة','Record payment'),()=>dialog(tr('تسجيل دفعة','Record payment'),form=>{field(form,'amount',tr('المبلغ المدفوع — ريال','Amount paid — SAR'),{type:'number',min:'.01',max:d.remaining,step:'.01',value:d.remaining,required:true});field(form,'paid_on',tr('تاريخ الدفع','Paid date'),{type:'date',value:today(),max:today(),required:true});field(form,'reference',tr('مرجع الدفع / رقم الحوالة','Payment reference / transfer number'),{required:true,wide:true});},async(v,key)=>{await api('advacon_housing_finance_command',{p_command_id:key,p_action:'payment.record',p_payload:{id:d.id,...v}});await refresh();}),true));
 body.querySelectorAll('[data-payment]').forEach(cell=>{const p=payments.find(x=>x.id===cell.dataset.payment);if(data.can_manage!==false&&!p.reversal_of&&!payments.some(x=>x.reversal_of===p.id))cell.append(button(tr('عكس','Reverse'),()=>dialog(tr('عكس الدفعة','Reverse payment'),form=>field(form,'reason',tr('سبب العكس','Reason'),{required:true,wide:true}),async(v,key)=>{await api('advacon_housing_finance_command',{p_command_id:key,p_action:'payment.reverse',p_payload:{id:p.id,...v}});await refresh();})));});
 if(data.can_manage!==false&&!d.bill_id&&!d.cancelled&&Number(d.paid)===0)footer.append(button(tr('إلغاء الاستحقاق','Cancel due'),()=>dialog(tr('إلغاء استحقاق مع حفظ سجله','Cancel due and retain history'),form=>field(form,'reason',tr('السبب','Reason'),{required:true,wide:true}),async(v,key)=>{await api('advacon_housing_finance_command',{p_command_id:key,p_action:'due.cancel',p_payload:{id:d.id,...v}});await refresh();})));
 if(d.bill_id)footer.append(button(tr('ملف الفاتورة','Bill file'),()=>openBillDetail(d.bill_id,refresh)));
}
async function ledgerScreen(el,propertyId=null,report=false){const data=await api('advacon_housing_ledger',{p_property_id:propertyId});if(!el.isConnected)return;const params=new URLSearchParams(location.hash.split('?')[1]);const status=params.get('status')||'open';el.innerHTML='<div class="hv-print-title"><h1>ADVACON — '+tr('كشف المستحقات والمدفوعات','Dues & payments statement')+'</h1></div><div class="hv-toolbar"><label>'+tr('من تاريخ استحقاق','Due from')+'<input name="from" type="date"></label><label>'+tr('إلى','To')+'<input name="to" type="date"></label><label>'+tr('الحالة','Status')+'<select name="status"><option value="all">'+tr('الكل','All')+'</option><option value="open">'+tr('غير مسدد بالكامل','Outstanding')+'</option><option value="late">'+tr('متأخر','Overdue')+'</option><option value="upcoming">'+tr('خلال 30 يومًا','Next 30 days')+'</option><option value="paid">'+tr('مسدد','Paid')+'</option><option value="cancelled">'+tr('ملغى / موقوف','Cancelled / held')+'</option></select></label><label>'+tr('النوع','Type')+'<select name="type"><option value="">'+tr('الكل','All')+'</option><option value="contract">'+tr('عقد','Contract')+'</option><option value="bill">'+tr('فاتورة','Bill')+'</option><option value="expense">'+tr('مصروف','Expense')+'</option></select></label><input name="search" type="search" aria-label="'+tr('بحث في المستحقات','Search dues')+'" placeholder="'+tr('العقد أو الجهة أو المكان','Contract, payee or place')+'"></div><p class="hv-report-filter hv-muted"></p><div class="hv-ledger-summary"></div><div class="hv-ledger-rows"></div>';let visible=[];el.querySelector('[name=status]').value=report?'all':status;const draw=()=>{const get=n=>el.querySelector('[name='+n+']').value,from=get('from'),to=get('to'),s=get('status'),type=get('type'),q=get('search').toLowerCase();const box=el.querySelector('.hv-ledger-rows');if(from&&to&&from>to){visible=[];box.innerHTML=empty(tr('تاريخ البداية بعد النهاية.','Start date is after end date.'));el.querySelector('.hv-ledger-summary').innerHTML='';return;}visible=data.dues.filter(d=>(s==='cancelled'?d.cancelled:!d.cancelled)&&(!from||!d.due_date_estimated&&d.due_date>=from)&&(!to||!d.due_date_estimated&&d.due_date<=to)&&(!type||d.source_type===type)&&(!q||[d.label,d.payee,...d.places.map(p=>p.name)].join(' ').toLowerCase().includes(q))&&(s!=='open'||Number(d.remaining)>0)&&(s!=='late'||Number(d.remaining)>0&&!d.due_date_estimated&&d.due_date<data.as_of)&&(s!=='upcoming'||Number(d.remaining)>0&&!d.due_date_estimated&&d.due_date>=data.as_of&&d.due_date<=addDays(data.as_of,30))&&(s!=='paid'||Number(d.remaining)<=0));
 el.querySelector('.hv-report-filter').textContent=tr('حسب تاريخ الاستحقاق: ','By due date: ')+(from||'—')+' / '+(to||'—')+' · '+el.querySelector('[name=status] option:checked').textContent+' · '+visible.length+' '+tr('سجل','records')+' · '+tr('الرصيد حتى ','Balance as of ')+data.as_of;
 el.querySelector('.hv-ledger-summary').innerHTML=kpis([[tr('قيمة النتائج','Results value'),fmtSAR(sum(visible,'amount'))],[tr('مدفوع على هذه النتائج','Paid against these results'),fmtSAR(sum(visible,'paid'))],[tr('المتبقي','Remaining'),fmtSAR(sum(visible,'remaining'))]]);
 box.innerHTML=visible.length?table(dueHeaders(!report),dueRows(visible,data.as_of,!report)):empty();if(!report)bindDues(box,data,()=>ledgerScreen(el,propertyId,report));};el.querySelectorAll('input,select').forEach(x=>x.oninput=draw);const toolbar=el.querySelector('.hv-toolbar');toolbar.append(button(tr('تصدير CSV','Export CSV'),()=>exportCsv(visible,data.as_of)),button(tr('طباعة / PDF','Print / PDF'),()=>window.print()));draw();if(propertyId)el.insertAdjacentHTML('beforeend','<p class="hv-note">'+tr('الفاتورة المشتركة تظهر هنا بقيمتها الكاملة، ولا تُكرر في الإجمالي العام. توزيع تكلفتها متاح من ملف الفاتورة.','Shared bills are shown here at full value and counted once in the global ledger. Allocate costs from the bill file.')+'</p>');}
function exportCsv(rows,asof){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const values=[[tr('الوصف','Description'),tr('الجهة','Payee'),tr('المكان','Place'),tr('الاستحقاق','Due'),tr('المبلغ','Amount'),tr('مدفوع','Paid'),tr('متبقٍ','Remaining'),tr('الرصيد بتاريخ','Balance as of')],...rows.map(d=>[d.label,d.payee,d.places.map(p=>p.name).join(' / '),d.due_date_estimated?'':d.due_date,d.amount,d.paid,d.remaining,asof])];const url=URL.createObjectURL(new Blob(['\uFEFF'+values.map(x=>x.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ADVACON-Housing-Ledger.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
